// 태스크 생성/편집 모달
import { useState, useEffect, useRef } from 'react';
import type { Project, ProjectTask, ProjectTodo } from '../../types/work';
import { useDraggable } from '../../hooks/useDraggable';
import './TaskModal.css';

interface TaskModalProps {
  task: ProjectTask | null; // null이면 새 태스크 생성
  isOpen: boolean;
  projects: Project[]; // 프로젝트 목록
  todos: ProjectTodo[]; // 해당 태스크의 투두 목록
  defaultProjectId?: string | null;
  onClose: () => void;
  onSave: (task: Partial<ProjectTask>) => void;
  onDelete?: (taskId: string) => void;
  onTodoClick?: (todo: ProjectTodo) => void;
  onAddTodo?: (content: string) => void;
  onToggleTodo?: (todoId: string) => void;
}

export default function TaskModal({
  task,
  isOpen,
  projects,
  todos,
  defaultProjectId,
  onClose,
  onSave,
  onDelete,
  onTodoClick,
  onAddTodo,
  onToggleTodo,
}: TaskModalProps) {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [projectId, setProjectId] = useState<string | null>(null);
  const [startDate, setStartDate] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endDate, setEndDate] = useState('');
  const [endTime, setEndTime] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [dueTime, setDueTime] = useState('');
  const [isAllDay, setIsAllDay] = useState(true);
  const [newTodoContent, setNewTodoContent] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [dateError, setDateError] = useState('');
  
  const titleRef = useRef<HTMLInputElement>(null);
  const { position, isDragging, handleMouseDown, resetPosition } = useDraggable();
  
  // 날짜 유효성 검사
  const validateDates = (): boolean => {
    if (startDate && endDate) {
      const startDT = new Date(`${startDate}T${startTime || '00:00'}`);
      const endDT = new Date(`${endDate}T${endTime || '23:59'}`);
      if (endDT < startDT) {
        setDateError('종료일은 시작일보다 이후여야 합니다');
        return false;
      }
    }
    setDateError('');
    return true;
  };
  
  // 날짜+시간 결합
  const combineDateTime = (date: string, time: string, defaultTime: string): string | null => {
    if (!date) return null;
    return `${date}T${time || defaultTime}:00`;
  };

  const isNew = !task;

  useEffect(() => {
    if (isOpen) {
      if (task) {
        setTitle(task.title);
        setDescription(task.description || '');
        setProjectId(task.projectId);
        setIsAllDay(task.is_all_day);
        
        // 날짜/시간 파싱
        if (task.start_at) {
          const [d, t] = task.start_at.split('T');
          setStartDate(d);
          setStartTime(t ? t.slice(0, 5) : '');
        } else {
          setStartDate('');
          setStartTime('');
        }
        if (task.end_at) {
          const [d, t] = task.end_at.split('T');
          setEndDate(d);
          setEndTime(t ? t.slice(0, 5) : '');
        } else {
          setEndDate('');
          setEndTime('');
        }
        if (task.due_at) {
          const [d, t] = task.due_at.split('T');
          setDueDate(d);
          setDueTime(t ? t.slice(0, 5) : '');
        } else {
          setDueDate('');
          setDueTime('');
        }
      } else {
        // 새 태스크
        setTitle('');
        setDescription('');
        setProjectId(defaultProjectId || null);
        setIsAllDay(true);
        setStartDate('');
        setStartTime('');
        setEndDate('');
        setEndTime('');
        setDueDate('');
        setDueTime('');
        setNewTodoContent('');
      }
      setDateError('');
      resetPosition();
      setTimeout(() => titleRef.current?.focus(), 100);
    }
  }, [isOpen, task, defaultProjectId, resetPosition]);

  const handleSave = async () => {
    if (!title.trim() || isSaving) return;
    if (!validateDates()) return;
    
    setIsSaving(true);
    try {
      await onSave({
        ...task,
        title: title.trim(),
        description: description.trim(),
        projectId,
        is_all_day: isAllDay,
        start_at: combineDateTime(startDate, isAllDay ? '' : startTime, '00:00'),
        end_at: combineDateTime(endDate, isAllDay ? '' : endTime, '23:59'),
        due_at: combineDateTime(dueDate, isAllDay ? '' : dueTime, '23:59'),
      });
      onClose();
    } catch (error) {
      console.error('Failed to save task:', error);
      alert('저장에 실패했습니다.');
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = () => {
    if (!task || !onDelete) return;
    if (confirm('정말로 이 Task를 삭제하시겠습니까?\n소속된 모든 To do도 함께 삭제됩니다.')) {
      onDelete(task.id);
      onClose();
    }
  };

  const handleAddTodo = () => {
    if (!newTodoContent.trim() || !onAddTodo) return;
    onAddTodo(newTodoContent.trim());
    setNewTodoContent('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      onClose();
    }
  };

  // 프로젝트 색상 가져오기
  const getProjectColor = (pId: string | null): string => {
    if (!pId) return '#6b7280';
    const project = projects.find(p => p.id === pId);
    return project?.color || '#6b7280';
  };

  if (!isOpen) return null;

  // 드래그된 위치가 있으면 적용
  const modalStyle = position ? {
    position: 'fixed' as const,
    left: position.x,
    top: position.y,
    margin: 0,
  } : undefined;

  return (
    <div className="task-modal-overlay" onClick={onClose} onKeyDown={handleKeyDown}>
      <div 
        className={`task-modal ${isDragging ? 'dragging' : ''}`} 
        onClick={(e) => e.stopPropagation()}
        style={modalStyle}
      >
        {/* 헤더 - 드래그 핸들 */}
        <div 
          className="modal-header draggable" 
          onMouseDown={handleMouseDown}
          style={{ borderLeftColor: getProjectColor(projectId) }}
        >
          <h2>{isNew ? 'New Task' : 'Edit Task'}</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        {/* 본문 */}
        <div className="modal-body">
          {/* 제목 */}
          <div className="form-group">
            <label>제목 *</label>
            <input
              ref={titleRef}
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="태스크 제목"
              onKeyDown={(e) => e.key === 'Enter' && handleSave()}
            />
          </div>

          {/* 소속 프로젝트 */}
          <div className="form-group">
            <label>소속 프로젝트</label>
            <select
              value={projectId || ''}
              onChange={(e) => setProjectId(e.target.value || null)}
            >
              <option value="">프로젝트 없음</option>
              {projects.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.title}
                </option>
              ))}
            </select>
          </div>

          {/* 메모 */}
          <div className="form-group">
            <label>메모</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="태스크 설명"
              rows={2}
            />
          </div>

          {/* 종일 여부 */}
          <div className="form-group checkbox-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={isAllDay}
                onChange={(e) => setIsAllDay(e.target.checked)}
              />
              종일
            </label>
          </div>

          {/* 날짜/시간 섹션 */}
          <div className="form-group">
            <label>기간</label>
            <div className="datetime-inputs">
              <div className="datetime-field">
                <span className="datetime-label">시작</span>
                <input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                />
                {!isAllDay && (
                  <input
                    type="time"
                    value={startTime}
                    onChange={(e) => setStartTime(e.target.value)}
                  />
                )}
              </div>
              <div className="datetime-spacer" />
              <div className="datetime-field">
                <span className="datetime-label">종료</span>
                <input
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                />
                {!isAllDay && (
                  <input
                    type="time"
                    value={endTime}
                    onChange={(e) => setEndTime(e.target.value)}
                  />
                )}
              </div>
            </div>
            {dateError && <span className="error-text">{dateError}</span>}
          </div>

          <div className="form-group">
            <label>마감일</label>
            <div className="datetime-single">
              <input
                type="date"
                value={dueDate}
                onChange={(e) => setDueDate(e.target.value)}
              />
              {!isAllDay && (
                <input
                  type="time"
                  value={dueTime}
                  onChange={(e) => setDueTime(e.target.value)}
                />
              )}
            </div>
          </div>

          {/* 소속 To do (기존 태스크인 경우) */}
          {!isNew && (
            <div className="form-group todos-section">
              <label>To do ({todos.length})</label>
              
              {/* To do 추가 */}
              {onAddTodo && (
                <div className="add-todo-row">
                  <input
                    type="text"
                    value={newTodoContent}
                    onChange={(e) => setNewTodoContent(e.target.value)}
                    placeholder="새 To do 추가..."
                    onKeyDown={(e) => e.key === 'Enter' && handleAddTodo()}
                  />
                  <button 
                    type="button" 
                    className="add-todo-btn"
                    onClick={handleAddTodo}
                    disabled={!newTodoContent.trim()}
                  >
                    +
                  </button>
                </div>
              )}
              
              {/* To do 목록 */}
              <div className="todos-list">
                {todos.length === 0 ? (
                  <p className="empty-todos">To do가 없습니다</p>
                ) : (
                  todos.map((todo) => (
                    <div 
                      key={todo.id} 
                      className={`todo-item ${todo.is_done ? 'done' : ''}`}
                    >
                      <button 
                        className="todo-checkbox"
                        onClick={() => onToggleTodo?.(todo.id)}
                      >
                        {todo.is_done ? '✓' : '○'}
                      </button>
                      <span 
                        className="todo-content"
                        onClick={() => onTodoClick?.(todo)}
                      >
                        {todo.content}
                      </span>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>

        {/* 푸터 */}
        <div className="modal-footer">
          {!isNew && onDelete && (
            <button className="delete-btn" onClick={handleDelete}>
              삭제
            </button>
          )}
          <div className="footer-right">
            <button className="cancel-btn" onClick={onClose}>
              취소
            </button>
            <button 
              className="save-btn" 
              onClick={handleSave}
              disabled={!title.trim() || isSaving}
            >
              {isSaving ? '저장 중...' : (isNew ? '생성' : '저장')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
